// Normalize the /earnings/fetch result and decide the branch (§3.2, §9.4).
// httpRequest onError:continueRegularOutput leaves an `error` object on failure;
// a partial scrape failure returns items with a summary prefixed "degraded:".
const fetch = $json;
const trigger = $('When Executed by Another Workflow').first().json;
const httpError = fetch.error !== undefined || fetch.items === undefined;
const items = Array.isArray(fetch.items) ? fetch.items : [];
const summary = (fetch.summary || '').toString();
const degradedFetch = httpError || summary.startsWith('degraded:');
const windowDays = Number(trigger.window_days) || null;
return [{ json: {
  ticker: trigger.ticker,
  run_id: trigger.run_id,
  window_days: windowDays,
  items,
  few_shot: Array.isArray(fetch.few_shot) ? fetch.few_shot : [],
  fetch_summary: summary || (httpError ? 'earnings fetch failed' : ''),
  has_items: items.length > 0,
  degraded_fetch: degradedFetch,
} }];

// Maya fetch failed/degraded with no disclosures (§9.4): explicit reason,
// no fabrication. Risk Manager downgrades conviction.
const c = $('Prep Fetch').first().json;
return [{ json: {
  ticker: c.ticker,
  selected_disclosure: null,
  considered: [],
  is_earnings_window: false,
  materiality: null,
  summary: `degraded: ${c.fetch_summary || 'maya fetch failed'}`,
  status: 'degraded',
} }];

// Healthy scrape, zero matching disclosures: a valid "no recent disclosure"
// result (§13, §14). Never padded.
const c = $('Prep Fetch').first().json;
const w = c.window_days ? ` in the last ${c.window_days}d` : ' in the disclosure window';
return [{ json: {
  ticker: c.ticker,
  selected_disclosure: null,
  considered: [],
  is_earnings_window: false,
  materiality: 'low',
  summary: `No recent Maya disclosures${w}.`,
  status: 'ok',
} }];

// Build one few-shot classify/translate prompt per ranked candidate (§3.2, §7).
// /earnings/fetch returns items ranked by relevance and excerpts only the top
// `earnings_candidates`, so the ones carrying an excerpt are exactly the ones
// worth an LLM call. Each becomes its own item: the Classify chain below runs
// once per item, so `kind`/`materiality` stay the model's judgement on every
// candidate — the server-side rank only chose who gets asked (§3.2 step 2).
// Only titles + bounded excerpts traverse the LLM, never raw pages (§2).
const c = $('Prep Fetch').first().json;
let cands = c.items
  .map((it, i) => ({ ...it, cand_idx: i }))
  .filter((it) => it.excerpt);
// Every PDF failed: still classify the top-ranked disclosure from its title
// alone rather than dropping the ticker. Figures will vote "ambiguous" (§9.4).
if (!cands.length && c.items.length) cands = [{ ...c.items[0], cand_idx: 0 }];

const shots = (c.few_shot || [])
  .map(e => `- (${e.language}) "${e.title}" — ${e.excerpt || ''} => kind=${e.kind}, materiality=${e.materiality} — ${e.reasoning}`)
  .join('\n');

return cands.map((cand) => {
  const prompt = [
    `You are the Earnings Agent for TA-35 ticker ${c.ticker}.`,
    'Classify the TASE (Maya) disclosure below and summarize it in English.',
    'kind must be one of: earnings, guidance, material_event, other.',
    'materiality must be one of: low, medium, high.',
    'If the disclosure is in Hebrew, set title_en to a faithful English translation of the title; if it is already in English, set title_en to null.',
    'Base everything only on the text provided. Do not state any financial figure in the summary unless it appears verbatim in the text.',
    '',
    'Labeled examples:',
    shots || '(none)',
    '',
    'Disclosure:',
    `language: ${cand.language}`,
    `title: ${cand.title}`,
    `text: ${cand.excerpt || '(no further text available)'}`,
    '',
    'Respond with ONLY a JSON object, no markdown fences, exactly this shape:',
    '{"kind":"<earnings|guidance|material_event|other>","materiality":"<low|medium|high>","summary":"<English, under 500 chars>","title_en":<string or null>}',
  ].join('\n');
  return { json: { ticker: c.ticker, run_id: c.run_id, cand_idx: cand.cand_idx, prompt } };
});

// Parse one candidate's raw LLM text into a payload for POST /validate.
// A parse failure is NOT swallowed — it becomes an invalid payload so the
// validate -> retry -> degraded path handles it (§9.4). `cand_idx` is carried
// via item pairing so each classification stays tied to its own disclosure.
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return { json: { agent: 'earnings', cand_idx: $('Build Classify Prompt').item.json.cand_idx, payload, raw } };

// This candidate's classification passed schema validation — carry it forward.
const p = $('Parse Classification').item.json;
return { json: {
  cand_idx: p.cand_idx,
  kind: p.payload.kind,
  materiality: p.payload.materiality,
  summary: p.payload.summary,
  title_en: p.payload.title_en ?? null,
  cls_degraded: false,
  cls_reason: null,
} };

// One automatic retry per candidate with a stricter instruction (§9.4); the
// /validate errors are quoted back to the model.
const base = $('Build Classify Prompt').item.json;
const errors = $json.errors || [];
const prompt = base.prompt
  + '\n\nYour previous response was rejected by schema validation: '
  + JSON.stringify(errors)
  + '\nRespond again with ONLY the JSON object described above — no prose, no markdown '
  + 'fences, no extra keys. kind and materiality MUST use exactly the allowed enum values.';
return { json: { cand_idx: base.cand_idx, prompt } };

// Parse the stricter retry for one candidate (§9.4).
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return { json: { agent: 'earnings', cand_idx: $('Build Stricter Classify').item.json.cand_idx, payload, raw } };

const p = $('Parse Classification (Retry)').item.json;
return { json: {
  cand_idx: p.cand_idx,
  kind: p.payload.kind,
  materiality: p.payload.materiality,
  summary: p.payload.summary,
  title_en: p.payload.title_en ?? null,
  cls_degraded: false,
  cls_reason: null,
} };

// This candidate failed validation twice — degrade its classified fields only
// (§9.4). It can still be selected if nothing else classified, in which case
// extraction runs on the verbatim text and nothing is guessed.
const errors = $json.errors || [];
return { json: {
  cand_idx: $('Build Stricter Classify').item.json.cand_idx,
  kind: null,
  materiality: null,
  summary: '',
  title_en: null,
  cls_degraded: true,
  cls_reason: 'classification failed schema validation after one stricter retry'
    + (errors.length ? ` (${errors.join('; ')})` : ''),
} };

// Emit three identical extraction tasks (§3.2 self-consistency, n=3) for the
// SELECTED disclosure. The single Extract chain below runs once per item at
// temperature 0.3 = three independent samples. The selection + its classification
// ride along for the vote and assemble nodes.
const pick = $json;
const c = $('Prep Fetch').first().json;
const sel = c.items[pick.selected.cand_idx];
const prompt = [
  `You are extracting headline financial figures from a TASE (Maya) disclosure about ${c.ticker}.`,
  'Fields: revenue, eps, guidance.',
  'Rules:',
  '- A value must be copied VERBATIM (character-for-character, including currency symbol and units) from the text below.',
  '- If a figure is not stated explicitly in the text, use null for that field.',
  '- NEVER compute, convert, sum, infer, or guess a number. For Hebrew text, copy the figure exactly as written; do not translate units.',
  '',
  'Text:',
  `title: ${sel.title}`,
  `text: ${sel.excerpt || '(no further text available)'}`,
  '',
  'Respond with ONLY a JSON object, no markdown fences, exactly this shape:',
  '{"revenue":<string or null>,"eps":<string or null>,"guidance":<string or null>}',
].join('\n');
return [1, 2, 3].map(n => ({ json: {
  sample: n,
  prompt,
  classification: pick.selected,
  considered: pick.considered,
  n_classified: pick.n_classified,
} }));

// Parse one extraction sample into a candidate payload for POST /validate.
// A parse failure is NOT swallowed — it becomes an invalid payload so the
// validate -> retry -> non-vote path handles it (§9.4).
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return { json: { agent: 'earnings_extraction', sample: $('Make 3 Samples').item.json.sample, payload, raw } };

// Sample passed schema validation — it becomes a vote.
const p = $('Parse Samples').item.json;
return { json: { sample: p.sample, payload: p.payload } };

// One automatic retry per sample with a stricter instruction (§9.4); the
// /validate errors are quoted back to the model.
const orig = $('Parse Samples').item.json;
const base = $('Make 3 Samples').item.json.prompt;
const errors = $json.errors || [];
const prompt = base
  + '\n\nYour previous response was rejected by schema validation: '
  + JSON.stringify(errors)
  + '\nRespond again with ONLY the JSON object described above — no prose, no markdown '
  + 'fences, no extra keys. Each field must be either a string copied verbatim from the text or null.';
return { json: { sample: orig.sample, prompt } };

// Parse one retried extraction sample for POST /validate (§9.4).
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return { json: { agent: 'earnings_extraction', sample: $('Build Stricter Extract').item.json.sample, payload, raw } };

// Sample failed validation twice — it becomes a NON-vote (payload null), so it
// can never help commit a figure. With fewer than 2 agreeing valid samples the
// field stays "ambiguous" (§3.2) — malformed output can only lose votes.
const sample = $('Build Stricter Extract').item.json.sample;
return { json: { sample, payload: null, reason: 'extraction sample failed schema validation after one stricter retry' } };

// §3.2 self-consistency commit: a figure is committed only when at least 2 of
// the 3 samples agree (string-exact after units normalization) on a non-null
// value -> {value: <verbatim string>, confidence: <2|3>}. Anything else ->
// {"value":"ambiguous","confidence":1}. Absent or disputed figures are never
// filled — the vote is deterministic code, not the LLM (§4.3 guardrail).
const samples = $input.all().map(i => i.json);
const valid = samples.filter(s => s.payload && typeof s.payload === 'object');
const FIELDS = ['revenue', 'eps', 'guidance'];
const norm = (s) => {
  if (s === null || s === undefined) return null;
  let t = String(s).toLowerCase().trim().replace(/\s+/g, ' ');
  t = t.replace(/,/g, '');
  t = t.replace(/\bbillions?\b/g, 'b').replace(/\bmillions?\b/g, 'm');
  t = t.replace(/מיליארד/g, 'b').replace(/מיליון/g, 'm');
  t = t.replace(/\bnis\b/g, '₪').replace(/\bils\b/g, '₪').replace(/ש"ח/g, '₪').replace(/שקלים/g, '₪').replace(/שקל/g, '₪');
  t = t.replace(/\s*([bm₪$%])\s*/g, '$1');
  return t;
};
const extracted = {};
for (const f of FIELDS) {
  const votes = valid
    .map(s => ({ raw: s.payload[f], key: norm(s.payload[f]) }))
    .filter(v => v.key !== null && v.key !== '');
  const counts = {};
  for (const v of votes) counts[v.key] = (counts[v.key] || 0) + 1;
  let committed = null;
  for (const [key, n] of Object.entries(counts)) {
    if (n >= 2 && (!committed || n > committed.n)) {
      committed = { n, raw: votes.find(v => v.key === key).raw };
    }
  }
  extracted[f] = committed
    ? { value: String(committed.raw), confidence: committed.n }
    : { value: 'ambiguous', confidence: 1 };
}
return [{ json: {
  extracted,
  n_samples: samples.length,
  n_valid: valid.length,
} }];

// Assemble the §3.2 output. The selected classification (or its degraded marker)
// and the considered list ride on Make 3 Samples; the voted figures arrive as
// $json. Any upstream failure degrades status explicitly (§9.4) — never silently.
const c = $('Prep Fetch').first().json;
const ms = $('Make 3 Samples').first().json;
const cls = ms.classification;
const considered = ms.considered || [];
const vote = $json;
const sel = c.items[cls.cand_idx];
const dateOnly = sel.published_at ? String(sel.published_at).slice(0, 10) : null;

const degraded = Boolean(c.degraded_fetch || cls.cls_degraded || vote.n_valid === 0);
const parts = [];
if (c.degraded_fetch) parts.push(c.fetch_summary || 'maya fetch degraded');
if (cls.cls_degraded) parts.push(cls.cls_reason || 'classification degraded');
if (vote.n_valid === 0) parts.push('all extraction samples failed validation');
let summary = cls.summary || `Disclosure: ${sel.title}`;
if (parts.length) summary = 'degraded: ' + parts.join('; ') + (cls.summary ? ' — ' + cls.summary : '');

// §3.4 reads "earnings window" as a recent results/guidance event: the selected
// in-window disclosure is one of those kinds. Degraded classification cannot
// assert a window.
const isWindow = !cls.cls_degraded && (cls.kind === 'earnings' || cls.kind === 'guidance');

const output = {
  ticker: c.ticker,
  selected_disclosure: {
    date: dateOnly,
    type: cls.cls_degraded ? null : cls.kind,
    language: sel.language,
    title: sel.title,
    url: sel.url,
    title_en: cls.title_en || null,
    summary: cls.cls_degraded ? null : cls.summary,
    extracted: vote.extracted,
  },
  considered,
  is_earnings_window: isWindow,
  materiality: cls.cls_degraded ? null : cls.materiality,
  summary,
  status: degraded ? 'degraded' : 'ok',
};

// Persist only the disclosure we actually classified/extracted (the selected one).
const store_rows = [{
  id: sel.id,
  published_at: sel.published_at || null,
  language: sel.language,
  title: sel.title,
  url: sel.url,
  kind: cls.cls_degraded ? null : cls.kind,
  materiality: cls.cls_degraded ? null : cls.materiality,
  summary: cls.cls_degraded ? null : cls.summary,
  extracted: vote.extracted,
}];

return [{ json: { output, store_rows, ticker: c.ticker } }];

// Persist result -> final §3.2 output. A failed write to the earnings table
// degrades the result rather than being silently ignored (§9.4).
const assembled = $('Assemble Output').first().json;
const persist = $json;
const out = { ...assembled.output };
const persistFailed = persist.error !== undefined || persist.stored === undefined;
if (persistFailed) {
  out.status = 'degraded';
  const base = out.summary || '';
  out.summary = (base.startsWith('degraded:') ? base : ('degraded: ' + base))
    + ' [persist to earnings table failed]';
}
return [{ json: out }];

// §3.2 step 3: select which classified candidate the agent actually reports.
// The newest filing is usually administrative, and the server-side rank only
// decided who got classified — the choice itself is made here, from the model's
// own kind/materiality, so a mis-ranked candidate simply loses.
// Highest materiality wins; ties break by kind, then recency. A degraded
// classification scores 0 and can only win if nothing else classified at all.
const c = $('Prep Fetch').first().json;
const cls = $input.all().map(i => i.json);

const MAT = { high: 3, medium: 2, low: 1 };
const KIND = { earnings: 4, guidance: 3, material_event: 2, other: 1 };
const when = (x) => {
  const it = c.items[x.cand_idx];
  return (it && it.published_at) || '';
};
const score = (x) => (x.cls_degraded ? 0 : (MAT[x.materiality] || 0));

const ranked = [...cls].sort((a, b) => {
  const m = score(b) - score(a);
  if (m) return m;
  const k = (KIND[b.kind] || 0) - (KIND[a.kind] || 0);
  if (k) return k;
  return String(when(b)).localeCompare(String(when(a)));
});

const selected = ranked[0];
// Everything classified but not selected — the §3.2 audit trail for the choice.
const considered = ranked.slice(1).map((x) => {
  const it = c.items[x.cand_idx] || {};
  return {
    date: it.published_at ? String(it.published_at).slice(0, 10) : null,
    title: it.title || '',
    url: it.url || '',
    kind: x.cls_degraded ? null : x.kind,
    materiality: x.cls_degraded ? null : x.materiality,
  };
});

return [{ json: { selected, considered, n_classified: cls.length } }];
